def shifted(m, dr, dc):
    a = np.zeros((4,4),int)
    src = np.array(m)
    for i in range(4):
        for j in range(4):
            ni, nj = i-dr, j-dc
            if 0<=ni<4 and 0<=nj<4: a[i,j]=src[ni,nj]
    return a

